  function configured(){return Boolean(cfg.supabaseUrl&&cfg.supabaseAnonKey)}
  function headers(token=session?.access_token){return{apikey:cfg.supabaseAnonKey||"",Authorization:`Bearer ${token||cfg.supabaseAnonKey||""}`,"Content-Type":"application/json"}}
  async function api(path,opt={},token){const r=await fetch(cfg.supabaseUrl.replace(/\/$/,"")+path,{...opt,headers:{...headers(token),...(opt.headers||{})}});const t=await r.text();let b;try{b=t?JSON.parse(t):null}catch{b=t}if(!r.ok)throw Error(b?.message||b?.msg||b?.error_description||b?.hint||`HTTP ${r.status}`);return b}
  function cloudPayload(table,obj){const val={...obj,user_id:session.user.id};if(table==="admin_profiles")delete val.user_id;return val}
  async function syncUpsert(table,obj,conflict){if(!session?.access_token||!configured())return false;try{await api(`/rest/v1/${table}?on_conflict=${conflict}`,{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify(cloudPayload(table,obj))});return true}catch(e){toast(`Saved locally; cloud sync failed: ${e.message}`);return false}}
  async function syncDelete(table,query){if(!session?.access_token)return;try{await api(`/rest/v1/${table}?${query}`,{method:"DELETE",headers:{Prefer:"return=minimal"}})}catch(e){toast(`Removed locally; cloud sync failed: ${e.message}`)}}
  async function pullCloud(){
    const tables=["workers","attendance","payments","business_transactions","orders"],slots={workers:"workers",attendance:"entries",payments:"payments",business_transactions:"businessTransactions",orders:"orders"};
    const results=await Promise.all([...tables,"business_days"].map(t=>api(`/rest/v1/${t}?select=*`).catch(()=>[])));
    const legacyRows=results[5]||[],legacy=legacyRows.flatMap(d=>{const out=[];if(Number(d.sales)>0)out.push({id:`legacy-${d.work_date}-sale`,work_date:d.work_date,kind:"sale",amount:Number(d.sales),note:d.note||"Imported daily sales",created_at:d.updated_at||new Date().toISOString()});if(Number(d.expenses)>0)out.push({id:`legacy-${d.work_date}-expense`,work_date:d.work_date,kind:"expense",amount:Number(d.expenses),note:d.note||"Imported daily expenses",created_at:d.updated_at||new Date().toISOString()});return out});
    const currentBusiness=results[3]||[];
    for(const date of new Set(legacyRows.map(d=>d.work_date))){let migrated=true;for(const row of legacy.filter(t=>t.work_date===date)){if(currentBusiness.some(t=>t.id===row.id))continue;if(!await syncUpsert("business_transactions",row,"id"))migrated=false}if(migrated)await syncDelete("business_days",`work_date=eq.${encodeURIComponent(date)}`)}
    for(let i=0;i<tables.length;i++){
      const table=tables[i],slot=slots[table],remote=table==="business_transactions"?[...legacy,...currentBusiness]:table==="orders"?(results[i]||[]).map(x=>x.order_data).filter(Boolean):(results[i]||[]),local=data[slot]||[],rowKey=x=>table==="attendance"?`${x.worker_id}:${x.work_date}`:x.id,map=new Map(remote.map(x=>[rowKey(x),x]));
      for(const x of local){const key=rowKey(x);if(!map.has(key)){map.set(key,x);const conflict=table==="attendance"?"user_id,worker_id,work_date":"id";await syncUpsert(table,table==="orders"?{id:x.id,order_data:x}:x,conflict)}}
      data[slot]=[...map.values()];
    }
    saveData();render();
    try{const prof=await api(`/rest/v1/admin_profiles?select=*&limit=1`);if(prof?.[0]){admin={...prof[0],invoicePrefix:prof[0].invoice_prefix||"INV",invoiceTerms:prof[0].invoice_terms||"",gstEnabled:prof[0].gst_enabled||false,gstRate:prof[0].gst_rate||0,gstType:prof[0].gst_type||"split",whatsapp:prof[0].whatsapp||"",gstin:prof[0].gstin||"",logo:prof[0].logo||""};saveAdmin();renderAdminButton()}else if(admin.name||admin.phone||admin.address)await syncUpsert("admin_profiles",adminCloudPayload(),"id")}catch{}
  }  async function auth(signup){if(!configured()){toast("Add Supabase URL and public key in config.js first");return}const email=$("#authEmail").value.trim(),password=$("#authPassword").value;$("#accountMessage").textContent="Connecting…";try{const result=await api(signup?"/auth/v1/signup":"/auth/v1/token?grant_type=password",{method:"POST",body:JSON.stringify({email,password})},cfg.supabaseAnonKey);if(!result.access_token){$("#accountMessage").textContent="Confirm your email, then sign in.";return}saveSession(result);await pullCloud();$("#accountMessage").textContent=`Signed in as ${result.user.email}`;toast("Cloud sync connected")}catch(e){$("#accountMessage").textContent=e.message}}
