function optimizeLogo(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(reader.error||new Error("Could not read logo"));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error("Choose a valid image file"));image.onload=()=>{try{const limit=720,scale=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext("2d");if(!context)throw new Error("Image compression is unavailable in this browser");context.drawImage(image,0,0,canvas.width,canvas.height);let result=canvas.toDataURL("image/webp",0.82);if(!result.startsWith("data:image/webp"))result=canvas.toDataURL("image/png");if(result.length>700000){canvas.width=Math.max(1,Math.round(canvas.width*.72));canvas.height=Math.max(1,Math.round(canvas.height*.72));context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);result=canvas.toDataURL("image/webp",0.68);if(!result.startsWith("data:image/webp"))result=canvas.toDataURL("image/png")}if(result.length>700000)throw new Error("This logo is still too large after compression. Choose a smaller image.");resolve(result)}catch(error){reject(error)}};image.src=reader.result};reader.readAsDataURL(file)})}
